mark_adjust :: Ed -> Linenr_T -> Linenr_T -> Int64 -> Int64 -> IO ()
mark_adjust ed' line1 line2 amount amount_after = do
  mark_adjust_internal ed' line1 line2 amount amount_after True
  pure ()

one_adjust :: Linenr_T -> Linenr_T -> Linenr_T -> Int64 -> Int64 -> Linenr_T
one_adjust lnum line1 line2 amount amount_after =
  if (lnum >= line1) && (lnum <= line2)
    then
      if amount == LONG_MAX
        then 0
        else lnum + amount
    else
      if (amount_after /= 0) && (lnum > line2)
        then lnum + amount_after
        else lnum

one_adjust_nodel :: Linenr_T -> Linenr_T -> Linenr_T -> Int64 -> Int64 -> Linenr_T
one_adjust_nodel lnum line1 line2 amount amount_after =
  if (lnum >= line1) && (lnum <= line2)
    then
      if amount == LONG_MAX
        then line1
        else lnum + amount
    else
      if (amount_after /= 0) && (lnum > line2)
        then lnum + amount_after
        else lnum

